import math
def priority(task, state, due_w=1.0, spt_w=0.05, age_w=0.01, c=3.0, demote=0.25, m=1e6, floor=0.2):
    ref = max(state.mean_est, 1.0)
    est = max(task.estimated_runtime, floor * ref, 1e-6)
    wait = max(0.0, state.now - task.release)
    inv = 1.0 / est

    score = -due_w * task.due / ref + spt_w * ref * inv + age_w * wait * inv

    if task.tenant == 'premium':
        slack = task.due - state.now - est
        backlog = state.queue_work / max(state.capacity, 1e-6)
        guard = c * max(ref, backlog, est)

        if slack <= guard:
            return m + (guard - slack) / max(guard, 1e-6) + 0.01 * score
        else:
            return score - demote * (slack / max(guard, 1e-6))

    return score

import math
def priority(task, state, k=1.0, age=0.05, risk_c=3.0, m=1e6, demote=0.15, floor=0.2, fit=0.1, core=0.01, map_f=0.9, reduce_f=1.0, join_f=1.1, other_f=1.0, late_cap=10.0):
    ref = max(state.mean_est, 1.0)
    if task.task_type == 'map':
        tf = map_f
    elif task.task_type == 'reduce':
        tf = reduce_f
    elif task.task_type == 'join':
        tf = join_f
    else:
        tf = other_f
    est = max(task.estimated_runtime, floor * ref, 1e-6) * max(tf, 1e-6)
    inv = 1.0 / est
    wait = max(0.0, state.now - task.release)
    slack = task.due - state.now - est
    denom = max(k * ref, 1e-6)
    if slack >= 0.0:
        atc = inv * math.exp(-slack / denom)
    else:
        atc = inv * (1.0 + min(late_cap, -slack / denom))
    base = atc + age * wait / ref
    if task.resource_need <= state.free:
        base += fit * inv
    base -= core * task.resource_need / ref
    if task.tenant == 'premium':
        backlog = state.queue_work / max(state.capacity, 1e-6)
        risk = risk_c * max(ref, backlog, est)
        if slack <= risk:
            return m + (risk - slack) / max(risk, 1e-6) + 0.01 * base
        else:
            return base - demote * (slack / max(risk, 1e-6))
    return base

