import math
def priority(task, state, k=0.6, m=5.0, b=0.8, c=2.0):
    p = max(task.estimated_runtime, 1e-6)
    mean_est = max(state.mean_est, 1e-6)
    wait = max(0.0, state.now - task.release)
    slack = task.due - p - state.now
    base = task.weight / p * math.exp(-max(0.0, slack) / (k * mean_est))
    if task.tenant == 'premium':
        late = max(0.0, -slack)
        overdue = min(10.0, late / mean_est)
        return m * base * (1.0 + c * overdue) * math.exp(min(5.0, late / mean_est))
    else:
        age = max(0.0, wait - c * p)
        return base * math.exp(min(8.0, b * age / mean_est))
