import math
def priority(task, state, k=0.5, m=7.5, b=1.2, c=2.5, theta=1.5, short=1.0, cap=15.0, load_w=0.8, rn_w=0.2, power=0.5):
    p = max(task.estimated_runtime, 1e-6)
    cores = max(task.resource_need, 1e-6)
    mean_est = max(state.mean_est, 1e-6)
    now = state.now
    wait = max(0.0, now - task.release)
    slack = task.due - p - now
    load = state.queue_work / max(state.capacity * mean_est, 1e-6)
    if task.tenant == 'premium':
        late = max(0.0, -slack)
        near = max(0.0, c * mean_est - slack) / max(c * mean_est, 1e-6)
        return m * (task.weight / p) * math.exp(-max(0.0, slack) / max(k * mean_est, 1e-6)) * math.exp(min(cap, late / mean_est)) * (1.0 + near) / (1.0 + rn_w * cores)
    else:
        is_short = 1.0 if p <= short * mean_est else 0.0
        boost = 1.0 + b * is_short
        age = 1.0 + wait / max(c * mean_est, 1e-6)
        size_pen = max(p * (1.0 + rn_w * cores), 1e-6)
        if load > theta:
            expo = 1.0 + load_w * load
            age_term = math.exp(min(cap, expo * math.log(age)))
            return task.weight * boost / size_pen * age_term * (1.0 + load)
        else:
            atc = task.weight / p * math.exp(-max(0.0, slack) / max(k * mean_est, 1e-6))
            age_term = math.exp(min(cap, power * math.log(age)))
            return atc * boost / max(1.0 + rn_w * cores, 1e-6) * age_term * (1.0 + load_w * load)

